import json

WS = '/home/agent/workspace/rl_contract'
with open(f'{WS}/environment_spec.json') as f:
    spec = json.load(f)

deltas = {a['id']: tuple(a['delta']) for a in spec['actions']}
rows, cols = spec['grid']['rows'], spec['grid']['cols']
in_grid = lambda s: 0 <= s[0] < rows and 0 <= s[1] < cols
step = lambda s, a: (max(0, min(s[0] + deltas[a][0], rows - 1)),
                     max(0, min(s[1] + deltas[a][1], cols - 1)))

terminals = {tuple(t) for t in spec['terminal_states']}
issues = []

with open(f'{WS}/trajectories.jsonl') as f:
    lines = [l for l in f.read().splitlines() if l.strip()]

print(f'{len(lines)} trajectory lines found')
for i, line in enumerate(lines, 1):
    try:
        t = json.loads(line)
    except Exception as e:
        issues.append(f'T{i}: invalid JSON -> {e}')
        continue

    keys = {'states', 'actions', 'rewards', 'dones'}
    if not keys.issubset(t):
        issues.append(f'T{i}: missing keys {keys - set(t)}')
        continue

    n = len(t['states'])
    lens = {k: len(t[k]) for k in keys}
    if len(set(lens.values())) != 1:
        issues.append(f'T{i}: unequal lengths {lens}')
        continue
    if n == 0:
        issues.append(f'T{i}: empty arrays')
        continue

    # Replay: states[k] is the pre-action state of step k
    if tuple(t['states'][0]) != tuple(spec['start_state']):
        issues.append(f"T{i}: first state {t['states'][0]} != start {spec['start_state']}")
    prev_r = None
    for k in range(n):
        s = tuple(t['states'][k])
        a = t['actions'][k]
        if not in_grid(s):
            issues.append(f'T{i} step {k}: state {s} outside grid')
            break
        if a not in deltas:
            issues.append(f'T{i} step {k}: invalid action id {a}')
            break
        nxt = step(s, a)
        done = bool(t['dones'][k])
        expected_done = nxt in terminals
        if done != expected_done:
            issues.append(f'T{i} step {k}: done={done} but next {nxt} terminal={expected_done}')
        expected_r = spec['rewards']['per_step']
        if t['rewards'][k] != expected_r:
            issues.append(f'T{i} step {k}: reward {t["rewards"][k]} != {expected_r}')
        if done and nxt not in terminals:
            issues.append(f'T{i} step {k}: terminal flag but {nxt} not terminal')
        # done must only be on last step
        if done and k != n - 1:
            issues.append(f'T{i} step {k}: done before last step')
    print(f'T{i}: {n} steps, lengths equal, replayed OK')

print()
if issues:
    print('ISSUES:')
    for x in issues:
        print(' -', x)
else:
    print('ALL TRAJECTORIES CONSISTENT WITH SPEC')
